<?php require_once "../includes/auth.php";require_login("student");require_once "../config/db.php";$id=$_SESSION["user"]["id"];$stmt=$conn->prepare("SELECT r.*,c.course_name,c.course_code FROM results r JOIN courses c ON r.course_id=c.id WHERE r.student_id=? ORDER BY c.course_code");$stmt->bind_param("i",$id);$stmt->execute();$rows=$stmt->get_result();$page_title="Results";$css_path="../assets/css/style.css";$js_path="../assets/js/main.js";require "../includes/header.php";?>
<div class="dashboard"><aside class="sidebar"><?php include "sidebar.php"; ?></aside><main class="dash-main"><h1>My Results</h1><div class="panel"><div class="table-wrap"><table><tr><th>Course</th><th>Marks</th><th>Grade</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r["course_code"]." - ".$r["course_name"])?></td><td><?=$r["marks"]?></td><td><b><?=e($r["grade"])?></b></td></tr><?php endwhile;?></table></div></div></main></div><?php require "../includes/footer.php"; ?>